insert into landowners(code,name,contact,billing_address) values ('L-RIMU','Rimu Station','Demo contact','Fictional Waikato address'),('L-KOWHAI','Kowhai Orchard','Demo contact','Fictional Bay of Plenty address') on conflict do nothing;
insert into sites(code,name,landowner_id,site_group,registration,location) values ('S-RIMU','Rimu North',(select id from landowners where code='L-RIMU'),'Waikato','DEMO-001','Fictional site, not a real coordinate'),('S-KOWHAI','Kowhai Orchard',(select id from landowners where code='L-KOWHAI'),'Bay of Plenty',null,'Fictional site'),('S-RIDGE','Rimu Ridge',(select id from landowners where code='L-RIMU'),'Waikato','DEMO-003','Fictional site') on conflict do nothing;
insert into statuses(code,site_id,recorded_on,hives,supers,strength,dead_hives,disease,queen_notes) values ('ST-R1',(select id from sites where code='S-RIMU'),current_date-38,48,60,'mixed',2,'none observed','4 queens to review'),('ST-K1',(select id from sites where code='S-KOWHAI'),current_date-5,32,32,'strong',0,'none observed','queenright') on conflict do nothing;
insert into jobs(code,site_id,name,due_on,assigned_to,cost_cents,labour_minutes) values ('J-ROUND',(select id from sites where code='S-RIMU'),'Spring brood check',current_date-3,'Demo team north',18000,120),('J-SUPER',(select id from sites where code='S-KOWHAI'),'Check super space',current_date+3,'Demo orchard team',9000,60) on conflict do nothing;
insert into inspections(code,site_id,inspected_on,inspector,hives_checked,afb,notes) values ('I-SUSPECT',(select id from sites where code='S-RIDGE'),current_date-8,'Demo beekeeper',12,'suspected','Fictional overdue notification evidence for smoke tests'),('I-CLEAR',(select id from sites where code='S-KOWHAI'),current_date-5,'Demo beekeeper',32,'clear','Demo observation, no official certificate') on conflict do nothing;
insert into treatments(code,site_id,applied_on,product,batch,instructions,removal_due,harvest_clear_on,cost_cents) values ('T-REMOVE',(select id from sites where code='S-RIMU'),current_date-50,'Demo treatment, not a recommendation','DEMO-B1','Fictional operator-supplied instructions',current_date-2,current_date+8,7200) on conflict do nothing;
insert into consumables(code,site_id,used_on,name,quantity,unit,cost_cents) values ('C-FEED',(select id from sites where code='S-RIMU'),current_date-60,'Sugar feed',30,'kg',4500) on conflict do nothing;
insert into harvests(code,site_id,harvested_on,boxes,kg,crop,declaration_ref,tutin_option,evidence_ref,processor) values ('H-RIMU',(select id from sites where code='S-RIMU'),current_date-100,24,420,'Mixed floral','DEMO-HD1','Operator recorded laboratory testing','DEMO-LAB1','Demo extraction shed'),('H-KOWHAI',(select id from sites where code='S-KOWHAI'),current_date-90,12,180,'Mixed floral',null,null,null,'Demo extraction shed') on conflict do nothing;
insert into batches(code,name,extracted_on,drum_ref) values ('B-SPRING','Demo extraction lot',current_date-85,'DEMO-DRUM1') on conflict do nothing;
insert into batch_inputs(code,batch_id,harvest_id,kg) select 'BI-1',(select id from batches where code='B-SPRING'),(select id from harvests where code='H-RIMU'),420 where not exists(select 1 from batch_inputs where code='BI-1');
insert into batch_inputs(code,batch_id,harvest_id,kg) select 'BI-2',(select id from batches where code='B-SPRING'),(select id from harvests where code='H-KOWHAI'),180 where not exists(select 1 from batch_inputs where code='BI-2');
insert into agreements(code,site_id,name,starts_on,ends_on,terms) values ('A-RIMU',(select id from sites where code='S-RIMU'),'Spring site access',current_date-300,current_date+12,'Review access and landowner terms before next season') on conflict do nothing;
insert into filings(code,name,kind,due_on,notes) values ('F-ADR','Annual Disease Return','ADR',make_date(extract(year from current_date)::int,6,1),'Demo: official submission evidence missing'),('F-COI','Certificate of Inspection, non-DECA operator','COI',make_date(extract(year from current_date)::int,11,30),'Operator must confirm current DECA status and all-hive coverage') on conflict do nothing;
